CORPUS = ['main ghar ja raha hoon', 'main school ja raha hoon', 'tum ghar ja rahe ho']
def bigram_prob(sentences, w1, w2):
    all_words = []
    for s in sentences:
        words = s.split()
        all_words.append('<s>')
        for w in words:
            all_words.append(w.lower())
        all_words.append('</s>')
    vocab = []
    for word in all_words:
        in_vocab = False
        for v in vocab:
            if v == word:
                in_vocab = True
        if in_vocab == False:
            vocab.append(word)
    V = len(vocab)
    count_w1_w2 = 0
    count_w1 = 0
    for s in sentences:
        words = ['<s>'] + s.lower().split() + ['</s>']
        for i in range(len(words) - 1):
            if words[i] == w1:
                count_w1 = count_w1 + 1
                if words[i+1] == w2:
                    count_w1_w2 = count_w1_w2 + 1
    prob = (count_w1_w2 + 1) / (count_w1 + V)
    return round(prob, 4)
def sentence_prob(sentences, sentence):
    words = ['<s>'] + sentence.lower().split() + ['</s>']
    total_p = 1.0
    for i in range(len(words) - 1):
        p = bigram_prob(sentences, words[i], words[i+1])
        total_p = total_p * p
    return round(total_p, 6)
print(bigram_prob(CORPUS, 'ja', 'raha'))

